// on the raw, the token-decoded, and this normalised form - the union covers
// every path that resolves under a gated namespace.
const collapse = (path: string): string => {
  const out: string[] = [];
  for (const seg of path.split("/")) {
    if (seg === "..") out.pop();
    else if (seg !== "." && seg !== "") out.push(seg);
  }
  return "/" + out.join("/");
};
const p = collapse(dec.replace(/\\/g, "/")).toLowerCase();
const rawLower = raw.toLowerCase();

const underNomadik =
  p === "/nomadik" ||
  p.startsWith("/nomadik/") ||
  rawLower === "/nomadik" ||
  rawLower.startsWith("/nomadik/");
const underHandymancf =
  p === "/handymanclonakilty" ||
  p.startsWith("/handymanclonakilty/") ||
  rawLower === "/handymanclonakilty" ||
  rawLower.startsWith("/handymanclonakilty/");
const underClient =
  p === "/client" ||
  p.startsWith("/client/") ||
  rawLower === "/client" ||
  rawLower.startsWith("/client/");
// Owner-only admin surface. Nested under /client so it must be tested BEFORE
// the tenant gate - a tenant session must never open it, and its own cookie
// (method 'owner') never opens a tenant's pages.
const underAdmin =
  p === "/client/admin" ||
  p.startsWith("/client/admin/") ||
  rawLower === "/client/admin" ||
  rawLower.startsWith("/client/admin/");
const underLab =
  p === "/lab" ||
  p.startsWith("/lab/") ||
  rawLower === "/lab" ||
  rawLower.startsWith("/lab/");
// /internal - owner-only personal tooling pages (currently just the
// email-ingest automation's hosted summaries). Same owner cookie as /lab.
const underInternal =
  p === "/internal" ||
  p.startsWith("/internal/") ||
  rawLower === "/internal" ||
  rawLower.startsWith("/internal/");
// The login pages and auth endpoints stay public (a viewer must be able to
// reach them without a session), and bypass the site-wide gate so sign-in
// works even while the rest of the site is in pre-launch lockdown.
// /api/internal/ is included here, NOT because it's public, but because it
// authenticates itself with a bearer token (lib/internal-ingest/auth.ts) -
// the email-ingest poller is a headless script with no browser cookie.
const isAuthEndpoint =
  p === "/client/login" ||
  p.startsWith("/api/client/") ||
  p === "/client/admin/login" ||
  p.startsWith("/api/admin/") ||
  p.startsWith("/api/internal/");

// --- Gate 1 (retired namespaces): both legacy docs now live in the /client
// portal. Permanent redirects so old bookmarks land on the portal login
// pre-filled with the workspace. ---
if (underNomadik) {
  return NextResponse.redirect(new URL("/client/login?c=nomadik", req.url), 308);
}
if (underHandymancf) {
  return NextResponse.redirect(new URL("/client/login?c=handymanclonakilty", req.url), 308);
}
// --- Gate 1.5: /client/admin (owner only; deny-by-default for the namespace).
// Checked before the tenant gate: a valid tenant session must NOT satisfy
// this gate, so it verifies the owner cookie exclusively. ---
if (underAdmin && !isAuthEndpoint) {
  const cookie = req.cookies.get(ADMIN_COOKIE)?.value;
  const ok = cookie ? await verifyAdminSessionEdge(cookie) : false;
  if (!ok) return NextResponse.redirect(new URL("/client/admin/login", req.url));
  return NextResponse.next();
}
// --- Gate 1.6: /lab (owner only). Design prototypes, never customer-facing.
// Deliberately the OWNER cookie and not the tenant one: a client has no
// reason to reach an internal prototype, and one of these pages names a
// product that has not launched. Bypassed under `next dev` so the board
// compositor script keeps working against a local server. ---
if (underLab && process.env.NODE_ENV !== "development") {
  const cookie = req.cookies.get(ADMIN_COOKIE)?.value;
  const ok = cookie ? await verifyAdminSessionEdge(cookie) : false;
  if (!ok) return NextResponse.redirect(new URL("/client/admin/login", req.url));
  return NextResponse.next();
}
// --- Gate 1.7: /internal (owner only, e.g. /internal/ingest). Same cookie
// and login redirect as /lab - a second personal-tooling namespace under the
// one existing owner session rather than a new auth mechanism. ---
if (underInternal && !isAuthEndpoint) {
  const cookie = req.cookies.get(ADMIN_COOKIE)?.value;
  const ok = cookie ? await verifyAdminSessionEdge(cookie) : false;
  if (!ok) return NextResponse.redirect(new URL("/client/admin/login", req.url));
  return NextResponse.next();
}
// --- Gate 2: /client portal (multi-tenant; deny-by-default for the namespace) ---
if (underClient && !isAuthEndpoint) {
  const cookie = req.cookies.get(CLIENT_COOKIE)?.value;
  const session = cookie ? await verifyClientSessionEdge(cookie) : null;
  if (!session) return NextResponse.redirect(new URL("/client/login", req.url));

  // /client/<slug>/... names a workspace explicitly - a multi-workspace
  // session may open any slug it was granted, not only its primary one.
  // Bare /client (no slug segment) has nothing to check here; ClientIndex
  // resolves it to the primary slug itself. An ungranted slug bounces to
  // the primary rather than denying outright, matching the old behaviour
  // of a single-workspace session hitting a foreign slug.
  const urlSlugMatch = p.match(/^\/client\/([a-z0-9-]+)/);
  const urlSlug = urlSlugMatch ? urlSlugMatch[1] : null;
  if (urlSlug && !sessionGrantsSlug(session, urlSlug)) {
    return NextResponse.redirect(new URL(`/client/${session.slug}`, req.url));
  }

  const headers = new Headers(req.headers);
  if (urlSlug) headers.set(PORTAL_ACTIVE_SLUG_HEADER, urlSlug);
  else headers.delete(PORTAL_ACTIVE_SLUG_HEADER);
  return NextResponse.next({ request: { headers } });
}
// --- Gate 2b: /client-docs/<slug>/* (per-tenant static reference docs) ---
// A client may only reach a slug their session was granted, so client A can
// never fetch client B's doc.
const docMatch = p.match(/^\/client-docs\/([a-z0-9-]+)(?:\/|$)/);
if (docMatch) {
  const docSlug = docMatch[1];
  const cookie = req.cookies.get(CLIENT_COOKIE)?.value;
  const session = cookie ? await verifyClientSessionEdge(cookie) : null;
  if (!session || !sessionGrantsSlug(session, docSlug)) {
    return NextResponse.redirect(new URL("/client/login", req.url));
  }
  return NextResponse.next();
}
// /api/client/* has no workspace in its own URL, so the active one is the
// portal page that issued the request: the same-origin Referer's
// /client/<slug>. Any client-sent copy of the header is dropped first, so the
// header only ever carries what the proxy derived. The route re-checks it
// against the session (lib/portal-editor/auth.ts); a multi-workspace session
// with no header is refused there, not defaulted to its primary.
if (p.startsWith("/api/client/")) {
  const headers = new Headers(req.headers);
  headers.delete(PORTAL_ACTIVE_SLUG_HEADER);
  const activeSlug = refererWorkspaceSlug(req);
  if (activeSlug) headers.set(PORTAL_ACTIVE_SLUG_HEADER, activeSlug);
  return NextResponse.next({ request: { headers } });
}
if (isAuthEndpoint) {
  return NextResponse.next();
}

// --- Offline surfaces: a route that exists in the repo but not on the site ---
// Checked here rather than with notFound() in the page, so /research/anything
// and any sub-path 404 together. A 404 rather than a redirect: "removed while
// I develop it" means a visitor finds nothing, and a redirect would advertise
// that the route is there. See lib/flags.ts.
// Gates on the normalised path AND the raw one, same belt-and-braces as the
// tenant prefixes above: an encoded or separator-variant path must not dodge
// this any more than it dodges those.

