import { NextResponse, type NextRequest } from "next/server";
import { CONSULTING_LIVE, RESEARCH_LIVE } from "@/lib/flags";
import { CLIENT_COOKIE, sessionGrantsSlug, verifyClientSessionEdge } from "./lib/client-auth-edge";
import { ADMIN_COOKIE, verifyAdminSessionEdge } from "./lib/admin-auth-edge";
import { PORTAL_ACTIVE_SLUG_HEADER } from "./lib/portal/active-slug-header";

// Three gates (checked in order), plus the retired-namespace redirects:
//
// 1. /nomadik (RETIRED 2026-08-03) and /handymanclonakilty (RETIRED 2026-07-14):
//    the two legacy single-tenant gated docs, both migrated fully into the
//    /client portal, so each namespace now permanent-redirects to the portal
//    login pre-filled with the workspace. Kept as explicit redirects (not 404s)
//    so the founders' old bookmarks keep working.
//
// 2. /client gate (always on): the multi-tenant AEO client dashboard. A signed
//    cookie (sol_client) carries method 'client' plus one or more granted
//    slugs (an email-based sign-in allowlisted into several workspaces gets
//    all of them at once - no per-workspace pick). Passwords are verified
//    against the per-client repo config (content/clients/<slug>/config.ts,
//    authHash = sha256(CLIENT_AUTH_PEPPER + password)) - not a database, not
//    the VPS, and not a shared env password; see lib/client-auth.ts.
//    Onboarding a client is therefore a repo change and does need a deploy.
//    /client/admin is the owner-only surface nested inside it and is checked
//    FIRST, so a tenant session can never open it.
//
// 3. /lab gate (always on in a deployed build): the nine design-prototype
//    routes. They carry noindex, which stops Google indexing them but does
//    NOT stop the sixteen AI crawlers robots.txt names by allowing them - and
//    /lab/work-treatments states an unlaunched product name and its status.
//    Owner cookie only, same as /client/admin. Bypassed in development so
//    `npm run boards` can still load /lab/board/<slug> off a local dev server
//    to screenshot it.
//
// 3.5. /internal gate (always on): owner-only personal-tooling pages, same
//    cookie as /lab. Currently just /internal/ingest - the hosted summaries
//    from the personal email-ingest automation. /api/internal/* is exempt
//    from THIS gate because it authenticates with its own bearer token
//    (lib/internal-ingest/auth.ts): the automation is a headless script, not
//    a browser, so it has no owner cookie to present.
//
// 4. Site-wide pre-launch gate (DORMANT by default): with no SITE_GATE_PASSWORD
//    set this is a no-op. Turned on/off purely by adding/removing
//    SITE_GATE_PASSWORD in Vercel - no code change. While active it returns 401
//    to everyone, including crawlers; remove the env var to launch.
/** The workspace slug of the same-origin portal page a request came from
 *  (Referer /client/<slug>/...), or null. Unverified here: the API route
 *  checks it against the session before acting on it. */
function refererWorkspaceSlug(req: NextRequest): string | null {
  const referer = req.headers.get("referer");
  if (!referer) return null;
  let url: URL;
  try {
    url = new URL(referer);
  } catch {
    return null;
  }
  if (url.origin !== req.nextUrl.origin) return null;
  const m = url.pathname.match(/^\/client\/([a-z0-9-]+)(?:\/|$)/);
  return m ? m[1] : null;
}

export async function proxy(req: NextRequest) {
  const raw = req.nextUrl.pathname;

  // Per-tenant reference docs are served as static files under public/client-docs.
  // Next/Vercel's static resolver percent-DECODES the URL before mapping it to a
  // file, but req.nextUrl.pathname is NOT decoded - so a raw string match here
  // would miss an encoded path (e.g. /client-docs/%6eomadik/x.html) and let it
  // fall through to the static file undecoded. Decode fully (looping is safe -
  // over-decoding only ever gates MORE) and lowercase to fold case, then gate on
  // BOTH the decoded and raw prefixes so nothing under a gated prefix can slip
  // past.
  //
  // Decode leniently, one %XX token at a time, rather than with a single
  // decodeURIComponent(dec) call: that built-in throws on the WHOLE string if
  // ANY token in it is malformed, which would let one bad byte anywhere in the
  // path (e.g. a trailing %zz) hide a perfectly valid /%6eomadik/ earlier in
  // the same path from this decoder while Vercel's resolver may still tolerate
  // it. Decoding token-by-token means a malformed token just stays literal
  // instead of aborting the whole decode.
  const lenientDecodeOnce = (s: string) =>
    s.replace(/%[0-9A-Fa-f]{2}/g, (tok) => {
      try {
        return decodeURIComponent(tok);
      } catch {
        return tok;
      }
    });
  let dec = raw;
  for (let i = 0; i < 5; i++) {
    const d = lenientDecodeOnce(dec);
    if (d === dec) break;
    dec = d;
  }
  // Also fold backslashes to "/" (an encoded %5C decodes to "\", which some
  // static resolvers treat as a separator) and collapse "." / ".." segments, so a
  // traversal or separator-variant the resolver would normalise INTO a gated file
  // (e.g. /api/client/..%2f..%2fclient-docs%2fnomadik%2freference.html)
  // can't dodge the prefix test or slip through the /api allowlist. We then gate
  // on the raw, the token-decoded, and this normalised form - the union covers
  // every path that resolves under a gated namespace.
  const collapse = (path: string): string => {
    const out: string[] = [];
    for (const seg of path.split("/")) {
      if (seg === "..") out.pop();
      else if (seg !== "." && seg !== "") out.push(seg);
    }
    return "/" + out.join("/");
  };
  const p = collapse(dec.replace(/\\/g, "/")).toLowerCase();
  const rawLower = raw.toLowerCase();

  const underNomadik =
    p === "/nomadik" ||
    p.startsWith("/nomadik/") ||
    rawLower === "/nomadik" ||
    rawLower.startsWith("/nomadik/");
  const underHandymancf =
    p === "/handymanclonakilty" ||
    p.startsWith("/handymanclonakilty/") ||
    rawLower === "/handymanclonakilty" ||
    rawLower.startsWith("/handymanclonakilty/");
  const underClient =
    p === "/client" ||
    p.startsWith("/client/") ||
    rawLower === "/client" ||
    rawLower.startsWith("/client/");
  // Owner-only admin surface. Nested under /client so it must be tested BEFORE
  // the tenant gate - a tenant session must never open it, and its own cookie
  // (method 'owner') never opens a tenant's pages.
  const underAdmin =
    p === "/client/admin" ||
    p.startsWith("/client/admin/") ||
    rawLower === "/client/admin" ||
    rawLower.startsWith("/client/admin/");
  const underLab =
    p === "/lab" ||
    p.startsWith("/lab/") ||
    rawLower === "/lab" ||
    rawLower.startsWith("/lab/");
  // /internal - owner-only personal tooling pages (currently just the
  // email-ingest automation's hosted summaries). Same owner cookie as /lab.
  const underInternal =
    p === "/internal" ||
    p.startsWith("/internal/") ||
    rawLower === "/internal" ||
    rawLower.startsWith("/internal/");
  // The login pages and auth endpoints stay public (a viewer must be able to
  // reach them without a session), and bypass the site-wide gate so sign-in
  // works even while the rest of the site is in pre-launch lockdown.
  // /api/internal/ is included here, NOT because it's public, but because it
  // authenticates itself with a bearer token (lib/internal-ingest/auth.ts) -
  // the email-ingest poller is a headless script with no browser cookie.
  const isAuthEndpoint =
    p === "/client/login" ||
    p.startsWith("/api/client/") ||
    p === "/client/admin/login" ||
    p.startsWith("/api/admin/") ||
    p.startsWith("/api/internal/");

  // --- Gate 1 (retired namespaces): both legacy docs now live in the /client
  // portal. Permanent redirects so old bookmarks land on the portal login
  // pre-filled with the workspace. ---
  if (underNomadik) {
    return NextResponse.redirect(new URL("/client/login?c=nomadik", req.url), 308);
  }
  if (underHandymancf) {
    return NextResponse.redirect(new URL("/client/login?c=handymanclonakilty", req.url), 308);
  }
  // --- Gate 1.5: /client/admin (owner only; deny-by-default for the namespace).
  // Checked before the tenant gate: a valid tenant session must NOT satisfy
  // this gate, so it verifies the owner cookie exclusively. ---
  if (underAdmin && !isAuthEndpoint) {
    const cookie = req.cookies.get(ADMIN_COOKIE)?.value;
    const ok = cookie ? await verifyAdminSessionEdge(cookie) : false;
    if (!ok) return NextResponse.redirect(new URL("/client/admin/login", req.url));
    return NextResponse.next();
  }
  // --- Gate 1.6: /lab (owner only). Design prototypes, never customer-facing.
  // Deliberately the OWNER cookie and not the tenant one: a client has no
  // reason to reach an internal prototype, and one of these pages names a
  // product that has not launched. Bypassed under `next dev` so the board
  // compositor script keeps working against a local server. ---
  if (underLab && process.env.NODE_ENV !== "development") {
    const cookie = req.cookies.get(ADMIN_COOKIE)?.value;
    const ok = cookie ? await verifyAdminSessionEdge(cookie) : false;
    if (!ok) return NextResponse.redirect(new URL("/client/admin/login", req.url));
    return NextResponse.next();
  }
  // --- Gate 1.7: /internal (owner only, e.g. /internal/ingest). Same cookie
  // and login redirect as /lab - a second personal-tooling namespace under the
  // one existing owner session rather than a new auth mechanism. ---
  if (underInternal && !isAuthEndpoint) {
    const cookie = req.cookies.get(ADMIN_COOKIE)?.value;
    const ok = cookie ? await verifyAdminSessionEdge(cookie) : false;
    if (!ok) return NextResponse.redirect(new URL("/client/admin/login", req.url));
    return NextResponse.next();
  }
  // --- Gate 2: /client portal (multi-tenant; deny-by-default for the namespace) ---
  if (underClient && !isAuthEndpoint) {
    const cookie = req.cookies.get(CLIENT_COOKIE)?.value;
    const session = cookie ? await verifyClientSessionEdge(cookie) : null;
    if (!session) return NextResponse.redirect(new URL("/client/login", req.url));

    // /client/<slug>/... names a workspace explicitly - a multi-workspace
    // session may open any slug it was granted, not only its primary one.
    // Bare /client (no slug segment) has nothing to check here; ClientIndex
    // resolves it to the primary slug itself. An ungranted slug bounces to
    // the primary rather than denying outright, matching the old behaviour
    // of a single-workspace session hitting a foreign slug.
    const urlSlugMatch = p.match(/^\/client\/([a-z0-9-]+)/);
    const urlSlug = urlSlugMatch ? urlSlugMatch[1] : null;
    if (urlSlug && !sessionGrantsSlug(session, urlSlug)) {
      return NextResponse.redirect(new URL(`/client/${session.slug}`, req.url));
    }

    const headers = new Headers(req.headers);
    if (urlSlug) headers.set(PORTAL_ACTIVE_SLUG_HEADER, urlSlug);
    else headers.delete(PORTAL_ACTIVE_SLUG_HEADER);
    return NextResponse.next({ request: { headers } });
  }
  // --- Gate 2b: /client-docs/<slug>/* (per-tenant static reference docs) ---
  // A client may only reach a slug their session was granted, so client A can
  // never fetch client B's doc.
  const docMatch = p.match(/^\/client-docs\/([a-z0-9-]+)(?:\/|$)/);
  if (docMatch) {
    const docSlug = docMatch[1];
    const cookie = req.cookies.get(CLIENT_COOKIE)?.value;
    const session = cookie ? await verifyClientSessionEdge(cookie) : null;
    if (!session || !sessionGrantsSlug(session, docSlug)) {
      return NextResponse.redirect(new URL("/client/login", req.url));
    }
    return NextResponse.next();
  }
  // /api/client/* has no workspace in its own URL, so the active one is the
  // portal page that issued the request: the same-origin Referer's
  // /client/<slug>. Any client-sent copy of the header is dropped first, so the
  // header only ever carries what the proxy derived. The route re-checks it
  // against the session (lib/portal-editor/auth.ts); a multi-workspace session
  // with no header is refused there, not defaulted to its primary.
  if (p.startsWith("/api/client/")) {
    const headers = new Headers(req.headers);
    headers.delete(PORTAL_ACTIVE_SLUG_HEADER);
    const activeSlug = refererWorkspaceSlug(req);
    if (activeSlug) headers.set(PORTAL_ACTIVE_SLUG_HEADER, activeSlug);
    return NextResponse.next({ request: { headers } });
  }
  if (isAuthEndpoint) {
    return NextResponse.next();
  }

  // --- Offline surfaces: a route that exists in the repo but not on the site ---
  // Checked here rather than with notFound() in the page, so /research/anything
  // and any sub-path 404 together. A 404 rather than a redirect: "removed while
  // I develop it" means a visitor finds nothing, and a redirect would advertise
  // that the route is there. See lib/flags.ts.
  // Gates on the normalised path AND the raw one, same belt-and-braces as the
  // tenant prefixes above: an encoded or separator-variant path must not dodge
  // this any more than it dodges those.
  const under = (prefix: string) => (s: string) =>
    s === prefix || s.startsWith(prefix + "/");
  const offline: Array<(s: string) => boolean> = [];
  if (!RESEARCH_LIVE) offline.push(under("/research"));
  if (!CONSULTING_LIVE) offline.push(under("/services/consulting"));
  if (offline.some((f) => f(p) || f(rawLower))) {
    // REWRITE, not an empty body (2026-09-06, stage 1 of the landing
    // reassessment). `new NextResponse(null, { status: 404 })` sent a zero-byte
    // 404, so a visitor following a stale link to /services/consulting got the
    // browser's own error page: no header, no footer, no way back into the
    // site, and nothing saying whose site she had reached. Rewriting to a path
    // that cannot exist makes Next render app/not-found.tsx, which is branded
    // and links home, while the status stays 404 so crawlers read it the same
    // way as before.
    return NextResponse.rewrite(new URL("/_offline", req.url), { status: 404 });
  }

  // --- Gate 4: site-wide pre-launch ---
  const password = process.env.SITE_GATE_PASSWORD;
  if (!password) return NextResponse.next(); // gate off

  const user = process.env.SITE_GATE_USER || "solaisoft";
  const header = req.headers.get("authorization") || "";

  if (header.startsWith("Basic ")) {
    try {
      const decoded = atob(header.slice(6));
      const sep = decoded.indexOf(":");
      const u = decoded.slice(0, sep);
      const pw = decoded.slice(sep + 1);
      if (u === user && pw === password) return NextResponse.next();
    } catch {
      // fall through to challenge
    }
  }

  return new NextResponse("Authentication required.", {
    status: 401,
    headers: {
      "WWW-Authenticate": 'Basic realm="Solaisoft preview", charset="UTF-8"',
      "Cache-Control": "no-store",
    },
  });
}

export const config = {
  // Gate everything except Next internals, the favicon, and the public brand
  // logo (linked from the email signature, so it must load without the gate).
  matcher: ["/((?!_next/static|_next/image|favicon.ico|solaisoft-logo-coral.png).*)"],
};

