import { beforeAll, describe, expect, it } from "vitest";
import { NextRequest } from "next/server";
import { proxy, config } from "../proxy";
import { CLIENT_COOKIE } from "../lib/client-auth-edge";

// Why this test exists
// --------------------
// The static client reference docs under public/client-docs/<slug>/ are the
// weakest link in the portal's confidentiality: they cannot run server code, so
// the ONLY thing standing between the public internet and one client's private
// data (Station Street Fitness's revenue, pricing, Wodify changes) is the edge
// gate in proxy.ts. The dynamic portal pages get a second layer (requireClient
// in the layout); the static docs get one. If that single control ever regresses
// - a broken slug comparison, a matcher that stops covering the path, a decode
// bypass - the docs would be exposed silently, with nothing to catch it.
//
// These tests execute the real gate and fail the build on any such regression.
// The positive control (right slug -> pass) is load-bearing: without it, a bug
// that redirected EVERYTHING would still pass every negative assertion.

const SECRET = "test-only-session-secret-not-used-in-prod-0123456789";
const TENANT_A = "station-street-fitness";
const TENANT_B = "nomadik";
const DOC_A = `https://solaisoft.com/client-docs/${TENANT_A}/reference.html`;

/**
 * Mint a valid /client session cookie, mirroring lib/client-auth.ts exactly:
 * base64(JSON{method:"client", slug, issuedAt}) + "." + hex(HMAC-SHA256(payload)).
 */
async function mintClientCookie(
  slug: string,
  secret: string,
  issuedAt: number = Date.now(),
): Promise<string> {
  const payload = btoa(JSON.stringify({ method: "client", slug, issuedAt }));
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const mac = new Uint8Array(
    await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(payload)),
  );
  const hex = Array.from(mac, (b) => b.toString(16).padStart(2, "0")).join("");
  return `${payload}.${hex}`;
}

function reqFor(url: string, cookie?: string): NextRequest {
  const headers = new Headers();
  if (cookie) headers.set("cookie", `${CLIENT_COOKIE}=${cookie}`);
  return new NextRequest(url, { headers });
}

/** True if the gate sent the caller to the client login (i.e. denied access). */
function deniedToLogin(res: Response): boolean {
  const location = res.headers.get("location") || "";
  return location.includes("/client/login");
}

beforeAll(() => {
  process.env.SESSION_SECRET = SECRET;
});

describe("proxy() gate on public/client-docs/<slug>", () => {
  it("wiring: the middleware matcher covers client-docs (never excluded)", () => {
    // If a future change adds client-docs to the matcher's exclusion list, the
    // gate would stop running for these paths and the docs would go public.
    for (const m of config.matcher) {
      expect(m).not.toContain("client-docs");
    }
    // And the catch-all still matches a real client-doc path.
    const matched = config.matcher.some((m) =>
      new RegExp(`^${m}$`).test(`/client-docs/${TENANT_A}/reference.html`),
    );
    expect(matched).toBe(true);
  });

  it("no cookie -> redirected to login", async () => {
    const res = await proxy(reqFor(DOC_A));
    expect(deniedToLogin(res)).toBe(true);
  });

  it("garbage cookie -> redirected to login", async () => {
    const res = await proxy(reqFor(DOC_A, "not-a-real-cookie.deadbeef"));
    expect(deniedToLogin(res)).toBe(true);
  });

  // The dogfood tenant's reference doc is the INTERNAL price sheet: it names
  // which clients are paying what, the margin on each line, and the founding
  // discount. Covered by the same path rule as any other doc, but asserted
  // explicitly because the cost of this one leaking is different in kind.
  it("the internal price sheet is gated, and a client's cookie cannot open it", async () => {
    const sheet = "https://solaisoft.com/client-docs/solaisoft/pricing.html";
    expect(deniedToLogin(await proxy(reqFor(sheet)))).toBe(true);

    const clientCookie = await mintClientCookie(TENANT_A, SECRET);
    expect(deniedToLogin(await proxy(reqFor(sheet, clientCookie)))).toBe(true);
  });

  it("cross-tenant: tenant B's valid cookie cannot open tenant A's doc", async () => {
    const cookieB = await mintClientCookie(TENANT_B, SECRET);
    const res = await proxy(reqFor(DOC_A, cookieB));
    expect(deniedToLogin(res)).toBe(true);
  });

  it("positive control: tenant A's valid cookie opens tenant A's doc", async () => {
    const cookieA = await mintClientCookie(TENANT_A, SECRET);
    const res = await proxy(reqFor(DOC_A, cookieA));
    // NextResponse.next() carries no location; a denial would redirect to login.
    expect(deniedToLogin(res)).toBe(false);
  });

  it("expired cookie (older than 7 days) -> redirected to login", async () => {
    const eightDaysAgo = Date.now() - 8 * 24 * 60 * 60 * 1000;
    const stale = await mintClientCookie(TENANT_A, SECRET, eightDaysAgo);
    const res = await proxy(reqFor(DOC_A, stale));
    expect(deniedToLogin(res)).toBe(true);
  });

  it("cookie signed with a different secret -> redirected to login", async () => {
    const forged = await mintClientCookie(TENANT_A, "attacker-guessed-secret");
    const res = await proxy(reqFor(DOC_A, forged));
    expect(deniedToLogin(res)).toBe(true);
  });

  it("path traversal cannot reach another tenant with A's cookie", async () => {
    // Resolves to /client-docs/nomadik/secret.html - a DIFFERENT slug - so A's
    // cookie must not open it. Guards the collapse()/normalise step in proxy.ts.
    const cookieA = await mintClientCookie(TENANT_A, SECRET);
    const traversal = `https://solaisoft.com/client-docs/${TENANT_A}/..%2f${TENANT_B}/secret.html`;
    const res = await proxy(reqFor(traversal, cookieA));
    expect(deniedToLogin(res)).toBe(true);
  });

  it("a multi-workspace session's granted slug opens its doc; an ungranted one is still denied", async () => {
    async function mintMultiWorkspaceCookie(primary: string, slugs: string[]): Promise<string> {
      const payload = btoa(JSON.stringify({ method: "client", slug: primary, slugs, issuedAt: Date.now() }));
      const key = await crypto.subtle.importKey(
        "raw",
        new TextEncoder().encode(SECRET),
        { name: "HMAC", hash: "SHA-256" },
        false,
        ["sign"],
      );
      const mac = new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(payload)));
      const hex = Array.from(mac, (b) => b.toString(16).padStart(2, "0")).join("");
      return `${payload}.${hex}`;
    }
    const cookie = await mintMultiWorkspaceCookie(TENANT_A, [TENANT_A, TENANT_B]);
    expect(deniedToLogin(await proxy(reqFor(DOC_A, cookie)))).toBe(false);
    const otherDoc = `https://solaisoft.com/client-docs/some-other-client/reference.html`;
    expect(deniedToLogin(await proxy(reqFor(otherDoc, cookie)))).toBe(true);
  });

  it("percent-encoded slug with no cookie is still gated", async () => {
    // /client-docs/%6eomadik/x.html decodes to /client-docs/nomadik/x.html.
    const encoded = "https://solaisoft.com/client-docs/%6eomadik/x.html";
    const res = await proxy(reqFor(encoded));
    expect(deniedToLogin(res)).toBe(true);
  });
});

