    const forged = await mintClientCookie("station-street-fitness", "attacker-guessed-secret");
    expect(deniedToLogin(await proxy(reqFor(url, forged)))).toBe(true);

    const valid = await mintClientCookie("station-street-fitness", SECRET);
    expect(deniedToLogin(await proxy(reqFor(url, valid)))).toBe(false);
  });
});

